<?php
declare(strict_types=1);
namespace BSPVisual;
require_once __DIR__.'/scenes.php';require_once dirname(__DIR__,2).'/museum/_lib/site.php';
use function BSPMuseum\h;use function BSPMuseum\j;
const COLORS=['#82d7ff','#ffce80','#83e4b8','#c6a5ff'];
function num($v):string{if(!is_numeric($v))return (string)$v;$v=(float)$v;return $v==0?'0':(abs($v)<.0001||abs($v)>=1e6?sprintf('%.5e',$v):rtrim(rtrim(sprintf('%.5f',$v),'0'),'.'));}
function point(array $d,float $x,float $y):array{return [65+($x-$d[0])/($d[1]-$d[0])*635,253-($y-$d[2])/($d[3]-$d[2])*215];}
function chart(array $r):void{$a=$r['candidate'];$d=$r['domain'];?><figure class="viz-chart"><svg viewBox="0 0 760 300" role="img" aria-label="Candidate and reference numerical curves on shared axes" id="viz-plot" xmlns="http://www.w3.org/2000/svg"><?php for($i=0;$i<=4;$i++):$y=253-$i*215/4;$x=65+$i*635/4;?><line class="viz-grid" x1="65" x2="700" y1="<?=$y?>" y2="<?=$y?>"/><text x="59" y="<?=$y+4?>" text-anchor="end"><?=h(num($d[2]+($d[3]-$d[2])*$i/4))?></text><text x="<?=$x?>" y="271" text-anchor="middle"><?=h(num($d[0]+($d[1]-$d[0])*$i/4))?></text><?php endfor;foreach(['reference','candidate'] as $side):if($side==='reference'&&$r['sameSweep'])continue;foreach($a['series'] as $i=>$label):$points=[];foreach($r[$side]['rows'] as $row){[$x,$y]=point($d,$row[0],$row[$i+1]);$points[]=sprintf('%.3f,%.3f',$x,$y);} ?><polyline fill="none" stroke="<?=COLORS[$i]?>" stroke-width="<?=$side==='reference'?1.7:2.5?>" <?=$side==='reference'?'stroke-dasharray="6 5" opacity=".72"':''?> points="<?=implode(' ',$points)?>"/><?php endforeach;endforeach;?><line id="viz-cursor" x1="65" x2="65" y1="38" y2="253" stroke="#fff" stroke-dasharray="3 4" visibility="hidden"/><g id="viz-markers"></g><text x="382" y="292" text-anchor="middle"><?=h($a['xLabel']??$a['x'])?></text></svg><figcaption><div class="viz-legend"><?php foreach($a['series'] as $i=>$label):?><span><svg viewBox="0 0 14 8" width="14" height="8" aria-hidden="true"><rect width="14" height="8" rx="2" fill="<?=COLORS[$i]?>"/></svg><?=h($label)?></span><?php endforeach;?></div><p class="muted">Solid: candidate. <?=$r['sameSweep']?'Reference sweep is identical and not drawn twice.':'Dashed: reference.'?> Shared numerical axes; the series retain their original units. Coincident curves may obscure one another.</p></figcaption></figure><?php }
function home():void{\BSPMuseum\start('Interactive visualization gallery','Nine interactive scientific visualizations driven by the existing foundation and evidence calculation engines.',ROOT);?><section class="intro"><span class="eyebrow gold">VISUAL SCIENCE · 2.1</span><h1>See what the mathematics predicts.</h1><p class="lead">Move through returned numerical samples, compare a reference and candidate, and connect the picture to a scientific test. No third-party graphics library or external service is required.</p><p class="notice">Time playback is provided only for time-dependent models. Other exhibits show parameter sweeps, not time evolution. The diagrams are teaching aids, not observations.</p></section><div class="grid viz-gallery"><?php foreach(scenes() as $id=>$s):?><article class="tile"><span class="eyebrow gold"><?=h($s['mode']==='time'?'TIME SERIES':'PARAMETER SWEEP')?></span><div class="viz-thumbnail viz-thumb-<?=h($id)?>"><img src="/visualizations/assets/<?=h($id)?>.svg" alt="" loading="lazy" width="640" height="275"></div><h2><a href="<?=ROOT.h($id)?>/"><?=h($s['title'])?></a></h2><p><?=h($s['description'])?></p><a href="<?=ROOT.h($id)?>/">Explore visualization →</a></article><?php endforeach;?></div><section class="section notice"><h2>Read the original research</h2><p>Each exhibit uses the same numerical solver as its linked foundation or evidence workbench. See the complete assumptions and evidence ledger before drawing conclusions.</p><a href="/evidence/">Evidence explorer</a> · <a href="/research/">Research workspace</a> · <a href="/visualizations/catalog.json">Machine catalog</a></section><?php \BSPMuseum\end();}
function page(string $id):void{$s=scenes()[$id];$m=\BSPResearch\models()[$s['model']];$error='';try{if(isset($_GET['p'])&&!is_array($_GET['p']))throw new \InvalidArgumentException('Expected a parameter object.');$r=solve_scene($id,input($_GET['p']??[]));}catch(\InvalidArgumentException $e){http_response_code(400);$error=$e->getMessage();$r=solve_scene($id);} $a=$r['candidate'];$b=$r['reference'];\BSPMuseum\start($s['title'],$s['description'],ROOT.$id.'/',!empty($_GET));?><section class="intro viz-intro"><a href="/visualizations/">← Visualization gallery</a><p class="eyebrow gold">VISUAL SCIENCE · <?=h($s['mode']==='time'?'TIME SERIES':'PARAMETER SWEEP')?></p><h1><?=h($s['title'])?></h1><p class="lead"><?=h($s['description'])?></p><p><strong>Research question:</strong> <?=h($s['question'])?></p></section><?php if($error):?><p role="alert" class="notice"><?=h($error)?> Default calculations shown.</p><?php endif;?><div class="viz-workspace"><section class="tile viz-main"><div class="viz-heading"><h2>Visual workbench</h2><span class="viz-label"><?=h($s['mode']==='time'?'Time samples':'Parameter samples')?></span></div><div class="viz-stage" id="viz-stage"><svg id="viz-diagram" viewBox="0 0 640 275" role="img" aria-label="Schematic view of numerical sample" hidden></svg><p id="viz-placeholder">Interactive diagrams require JavaScript. The numerical chart and table below are available without it.</p></div><div id="viz-controls" hidden><div class="viz-controls"><?php if($s['mode']==='time'):?><button class="button" id="viz-play" type="button">Play</button><?php endif;?><button class="button secondary" id="viz-prev" type="button" aria-label="Previous sample">←</button><button class="button secondary" id="viz-next" type="button" aria-label="Next sample">→</button><button class="button secondary" id="viz-reset" type="button">Reset sample</button></div><label for="viz-scrub">Inspect <?=h($s['mode']==='time'?'time':'parameter')?> sample</label><input type="range" id="viz-scrub" min="0" max="<?=count($a['rows'])-1?>" value="<?=$r['initialSample']?>" step="1"><p id="viz-position" class="muted"></p><div class="viz-readouts" id="viz-readouts"></div></div><p class="muted"><?=h($s['detail'])?></p><?php chart($r);?></section><aside class="tile viz-params"><h2>Change the parameters</h2><form method="get" action="<?=ROOT.h($id)?>/"><?php foreach($m['params'] as $p):?><label for="p-<?=h($p['key'])?>"><?=h($p['label'])?> <?=h($p['unit'])?></label><input id="p-<?=h($p['key'])?>" name="p[<?=h($p['key'])?>]" type="number" required min="<?=h($p['min'])?>" max="<?=h($p['max'])?>" step="any" value="<?=h($a['parameters'][$p['key']])?>"><small><?=h($p['min'])?> to <?=h($p['max'])?></small><?php endforeach;?><button class="button" type="submit">Recalculate both cases</button><a class="button secondary" href="<?=ROOT.h($id)?>/">Restore defaults</a></form><div class="viz-reference"><h3>Reference overrides</h3><p>Other parameters are held fixed.</p><?php foreach($r['referenceOverrides'] as $k=>$v):?><p><strong><?=h($k)?></strong> = <?=h(num($v))?></p><?php endforeach;?></div><a href="<?=h($m['url'])?>">Original numerical workbench →</a></aside></div><section class="section"><h2>Selected-parameter evidence</h2><p class="muted">These metrics are calculated at the exact form settings, independently of the scrubbed sample. A parameter sweep initially selects the nearest available sampled value.</p><div class="viz-table"><table><thead><tr><th scope="col">Quantity</th><th scope="col">Candidate</th><th scope="col">Reference</th></tr></thead><tbody><?php foreach($a['metrics'] as $i=>$v):?><tr><th scope="row"><?=h($v['label'])?> <?=h($v['unit'])?></th><td><?=h(num($v['value']))?></td><td><?=h(num($b['metrics'][$i]['value']))?></td></tr><?php endforeach;?></tbody></table></div><div class="actions" id="viz-exports" hidden><button class="button secondary" id="viz-json" type="button">Export both results (JSON)</button><button class="button secondary" id="viz-csv" type="button">Export sample arrays (CSV)</button></div><p><a href="<?=ROOT?>api/?<?=h(http_build_query(['scene'=>$id,'p'=>$a['parameters']]))?>">Open complete machine-readable result</a></p><details><summary>Numerical sample table (first 12 and last candidate samples)</summary><div class="viz-table"><table><thead><tr><?php foreach(array_merge([$a['xLabel']??$a['x']],$a['series']) as $v):?><th scope="col"><?=h($v)?></th><?php endforeach;?></tr></thead><tbody><?php foreach(array_merge(array_slice($a['rows'],0,12),count($a['rows'])>12?[end($a['rows'])]:[]) as $row):?><tr><?php foreach($row as $v):?><td><?=h(num($v))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div></details></section><section class="notice"><h2>Scientific limits</h2><p><?=h($a['limitation'])?></p><p>Source: <a href="<?=h($m['source']['url'])?>"><?=h($s['source_label'])?> ↗</a></p><a href="/evidence/">Inspect evidence</a> · <a href="/model-comparison/">Compare models</a> · <a href="/research/">Run an investigation</a></section><script type="application/json" id="viz-data"><?=j($r)?></script><?php \BSPMuseum\end();}
function api():void{\BSPMuseum\api_method();try{$id=$_GET['scene']??null;if(!is_string($id)||isset($_GET['p'])&&!is_array($_GET['p']))throw new \InvalidArgumentException('Provide a known scene and optional parameter object.');echo j(solve_scene($id,input($_GET['p']??[])));}catch(\InvalidArgumentException $e){http_response_code(400);echo j(['error'=>$e->getMessage()]);}}
